SELECT o.id,o.code,o.name,o.contact_name,o.contact_phone,o.contract_start,o.contract_end,o.status, o.remark,o.revision,o.created_at,o.updated_at,(SELECT COUNT(*) FROM client_campaign b WHERE b.tenant_id=o.tenant_id AND b.client_id=o.id) AS campaign_count,(SELECT COUNT(*) FROM client_user u WHERE u.tenant_id=o.tenant_id AND u.client_id=o.id) AS user_count,(SELECT COUNT(*) FROM client_lead l WHERE l.tenant_id=o.tenant_id AND l.client_id=o.id AND l.status='delivered' AND l.delivered_at >= #{since}) AS recent_leads FROM client_org o WHERE o.tenant_id=#{tenantId}
AND EXISTS(SELECT 1 FROM client_staff_scope s WHERE s.tenant_id=o.tenant_id AND s.client_id=o.id AND s.user_id=#{scopeUser})
AND o.status=#{status}
AND (o.name LIKE CONCAT('%',#{keyword},'%') OR o.code LIKE CONCAT('%',#{keyword},'%'))
ORDER BY o.id DESC LIMIT #{limit} OFFSET #{offset}

