mapper.select:
SELECT DATE(l.delivered_at) AS day,COUNT(*) AS delivered,COALESCE(SUM(l.follow_state IN ('valid','won')),0) AS valid,COALESCE(SUM(l.follow_state='invalid'),0) AS invalid FROM client_lead l WHERE l.tenant_id=#{tenantId} AND l.client_id=#{clientId} AND l.status='delivered' AND l.delivered_at >=#{from}
AND l.assignee_id=#{assignee}
GROUP BY DATE(l.delivered_at) ORDER BY day

SELECT l.campaign_id,g.name AS campaign_name,COUNT(*) AS
delivered,COALESCE(SUM(l.follow_state IN
('valid','won')),0) AS valid,COALESCE(SUM(l.follow_state='invalid'),0) AS invalid,
COALESCE(SUM(l.dispute_state='accepted'),0) AS disputes_accepted FROM client_lead l LEFT
JOIN campaign g ON
g.tenant_id=l.tenant_id AND g.id=l.campaign_id WHERE l.tenant_id=#{tenantId} AND
l.client_id=#{clientId}
AND l.status='delivered' AND l.delivered_at >=#{from}

    AND l.assignee_id=#{assignee}

GROUP BY l.campaign_id,g.name ORDER BY delivered DESC LIMIT 50

SELECT l.invalid_reason AS reason,COUNT(*) AS total FROM client_lead l WHERE
l.tenant_id=#{tenantId} AND
l.client_id=#{clientId} AND l.status='delivered' AND l.follow_state='invalid' AND
l.delivered_at >=#{from}

    AND l.assignee_id=#{assignee}

GROUP BY l.invalid_reason ORDER BY total DESC

SELECT COUNT(*) FROM client_lead_event WHERE tenant_id=#{tenantId} AND client_id=#{clientId}
AND
action=#{action} AND created_at >=#{since}

    AND actor_id=#{actorId} AND actor_kind='client'

SELECT COUNT(*) FROM client_staff_scope WHERE tenant_id=#{tenantId} AND
client_id=#{clientId} AND
user_id=#{userId}
